-- 019_knvbkalenderdag.sql — #1141 (Postgres-tier: "verzet zonder datum" met KNVB-bijlage en
-- vrije-zaterdagen-voorstel, #561-pariteit; deelstuk 3 van #972).
--
-- Postgres-tegenhanger van dbo.KnvbKalenderDag (Database/dbo/Tables/KnvbKalenderDag.sql) — de
-- landelijke KNVB-speeldagenkalender per regio/seizoen. Sportlink (his.matches) blijft autoritatief
-- voor concrete wedstrijden; deze tabel dient alleen om te bepalen of een zaterdag volgens de KNVB
-- gespeeld kan worden (Competitie/Beker/Inhaal) voor de "vrije zaterdagen"-suggestie in de
-- verzet-zonder-datum e-mailflow.
--
-- Identifier-casing: lowercase, ongequote — conform docs/ARCHITECTUUR-DATABASE-TIERS.md §3.
-- Landelijke KNVB-data zonder ClubCode-kolom, net als het SQL Server-origineel.
--
-- Seed hieronder is mechanisch overgenomen uit Database/Script.PostDeployment1.sql (regels
-- 405-1015, seizoenen 2025/2026 en 2026/2027, alle 8 seizoen/regio-blokken) — BIT 1/0 -> BOOLEAN
-- TRUE/FALSE, N'...' -> '...', [Kolom] -> kolom. Idempotent via ON CONFLICT DO NOTHING op de
-- primaire sleutel (seizoen, regio, datum) in plaats van de IF NOT EXISTS-per-blok-wrapper van het
-- origineel — functioneel gelijkwaardig, want de PK-kolommen zijn identiek aan de guard-kolommen.

CREATE TABLE IF NOT EXISTS public.knvbkalenderdag (
    seizoen VARCHAR(9) NOT NULL,
    regio VARCHAR(20) NOT NULL,
    datum DATE NOT NULL,
    dagtype VARCHAR(20) NOT NULL,
    heeftsenioren BOOLEAN NOT NULL,
    heeftjeugd BOOLEAN NOT NULL,
    heeftmeiden BOOLEAN NOT NULL,
    pupillentoernooi BOOLEAN NOT NULL DEFAULT FALSE,
    schoolvakantie VARCHAR(10) NULL,
    feestdag VARCHAR(50) NULL,
    opmerking VARCHAR(200) NULL,
    bron VARCHAR(200) NULL,
    CONSTRAINT pk_knvbkalenderdag PRIMARY KEY (seizoen, regio, datum),
    CONSTRAINT ck_knvbkalenderdag_dagtype CHECK (dagtype IN ('Competitie','Beker','Inhaal','Vrij','NC','Toernooi','Feestdag'))
);

CREATE INDEX IF NOT EXISTS ix_knvbkalenderdag_datum ON public.knvbkalenderdag (datum, regio, dagtype);

ON CONFLICT (seizoen, regio, datum) DO NOTHING;
